<template>
  <section class="section cats-page">
    <!-- 桌面端：拍立得乱序墙 -->
    <div class="cats-messy-wall desktop-only">
      <article 
        v-for="(cat, index) in cats" 
        :key="cat.id" 
        class="cat-polaroid neo-frame"
        :style="getCatStyle(index)"
      >
        <div class="polaroid-img" :style="{ background: cat.avatarBg }">
          <img :src="cat.image" :alt="cat.name" loading="lazy" decoding="async" />
          <HighlightTag 
            class="gender-tag" 
            :bg-color="cat.genderColor"
            text-color="#fff"
            padding="4px 8px"
            border="2px solid #000"
            font-size="12px"
          >
            {{ cat.gender === 'FEMALE' ? '♀' : '♂' }}
          </HighlightTag>
        </div>
        <div class="polaroid-content">
          <div class="cat-header">
            <span class="cat-name">{{ cat.name }}</span>
            <span v-if="cat.englishName" class="cat-loc">@{{ cat.englishName }}</span>
          </div>
          <div class="cat-tags">
            <span v-for="tag in cat.tags" :key="tag.text" class="mini-tag">
              #{{ tag.text }}
            </span>
          </div>
          <div class="cat-stats-row">
            <div class="stat-item">
              <small>BREED</small>
              <strong>{{ cat.breed }}</strong>
            </div>
            <div class="stat-item">
              <small>AGE</small>
              <strong>{{ cat.age }}</strong>
            </div>
            <div class="stat-item">
              <small>WEIGHT</small>
              <strong>{{ cat.weight }}</strong>
            </div>
          </div>
          <div class="cat-footer-id">{{ cat.catId }}</div>
        </div>
      </article>
    </div>

    <!-- 移动端：Swiper 轮播 -->
    <div class="mobile-only cat-carousel">
      <Swiper
        class="cat-swiper"
        :modules="swiperModules"
        :navigation="cats.length > 1"
        :pagination="{ clickable: true }"
        :loop="cats.length > 1"
        :slides-per-view="1"
        :space-between="16"
        :speed="450"
        :watch-overflow="true"
        :observer="true"
        :observe-parents="true"
      >
        <SwiperSlide
          v-for="cat in cats"
          :key="cat.id"
          class="cat-swiper-slide"
        >
          <article class="cat-polaroid neo-frame">
            <div class="polaroid-img" :style="{ background: cat.avatarBg }">
              <img :src="cat.image" :alt="cat.name" />
              <HighlightTag 
                class="gender-tag" 
                :bg-color="cat.genderColor"
                text-color="#fff"
                padding="4px 8px"
                border="2px solid #000"
                font-size="12px"
              >
                {{ cat.gender === 'FEMALE' ? '♀' : '♂' }}
              </HighlightTag>
            </div>
            <div class="polaroid-content">
              <div class="cat-header">
                <span class="cat-name">{{ cat.name }}</span>
                <span v-if="cat.englishName" class="cat-loc">@{{ cat.englishName }}</span>
              </div>
              <div class="cat-tags">
                <span v-for="tag in cat.tags" :key="tag.text" class="mini-tag">
                  #{{ tag.text }}
                </span>
              </div>
              <div class="cat-stats-row">
                <div class="stat-item">
                  <small>BREED</small>
                  <strong>{{ cat.breed }}</strong>
                </div>
                <div class="stat-item">
                  <small>AGE</small>
                  <strong>{{ cat.age }}</strong>
                </div>
                <div class="stat-item">
                  <small>WEIGHT</small>
                  <strong>{{ cat.weight }}</strong>
                </div>
              </div>
              <div class="cat-footer-id">{{ cat.catId }}</div>
            </div>
          </article>
        </SwiperSlide>
      </Swiper>
    </div>

    <div class="gallery-divider" aria-hidden="true">
      <span class="gallery-divider-title">CAT LOGS</span>
      <span class="gallery-divider-line"></span>
      <span class="gallery-divider-meta">GALLERY_VIEW_ALL</span>
    </div>
    <PhotoGrid :photos="photos" />
  </section>
</template>

<script>
import HighlightTag from '@/components/common/HighlightTag.vue'
import PhotoGrid from '@/components/gallery/PhotoGrid.vue'
import { Swiper, SwiperSlide } from 'swiper/vue'
import { Navigation, Pagination } from 'swiper/modules'
import 'swiper/css'
import 'swiper/css/navigation'
import 'swiper/css/pagination'
import cat1 from '@/assets/images/cat_1.webp'
import cat2 from '@/assets/images/cat_2.webp'
import cat3 from '@/assets/images/cat_3.webp'
import { CAT_PHOTOS } from '@/data/siteData'

export default {
  name: 'CatsView',
  components: { 
    Swiper,
    SwiperSlide,
    HighlightTag, 
    PhotoGrid
  },
  data() {
    return {
      swiperModules: [Navigation, Pagination],
      photos: CAT_PHOTOS,
      cats: [
        {
          id: 1,
          catId: 'CAT-01',
          name: '蛋挞',
          englishName: 'Paris',
          gender: 'FEMALE',
          genderColor: '#f472b6',
          avatarBg: '#fee2e2',
          breed: '英短金渐层',
          age: '5.5岁',
          weight: '5.2kg',
          image: cat1,
          tags: [{ text: '窗帘爱好者' }, { text: '键盘漫步专家' }]
        },
        {
          id: 2,
          catId: 'CAT-02',
          name: '揪揪',
          englishName: 'jiujiu',
          gender: 'MALE',
          genderColor: '#4D61FC',
          avatarBg: '#e0e7ff',
          breed: '美短',
          age: '5岁',
          weight: '6.5kg',
          image: cat2,
          tags: [ { text: '干饭王' }]
        },
        {
          id: 3,
          catId: 'CAT-03',
          name: '啊金',
          englishName: 'ajin',
          gender: 'MALE',
          genderColor: '#4D61FC',
          avatarBg: '#fef3c7',
          breed: '英短金渐层',
          age: '4岁',
          weight: '5kg',
          image: cat3,
          tags: [{ text: '社恐小猫' }]
        }
      ]
    }
  },
  methods: {
    getCatStyle(index) {
      const rotates = ['-3deg', '2deg', '-1.5deg'];
      const translates = ['-10px', '10px', '0px'];
      return {
        '--rotate': rotates[index % 3],
        '--translate-y': translates[index % 3],
        'z-index': 10 - index
      };
    }
  }
}
</script>

<style scoped>
.cats-page { padding-block: 24px 50px; }

/* 桌面端布局 */
.desktop-only { display: none; }
@media (min-width: 768px) {
  .desktop-only { display: flex; }
  .mobile-only { display: none; }
}

.cats-messy-wall {
  justify-content: center;
  align-items: center;
  padding: 60px 20px;
  min-height: 400px;
  perspective: 1000px;
  flex-wrap: wrap;
  gap: 40px;
}

/* 移动端：原生横向滚动 + Neo 按钮/分页 */
.cat-carousel {
  padding: 0 12px 12px;
  margin-bottom: 20px;
  overflow: hidden;
}

.cat-swiper {
  width: calc(100% - 28px);
  overflow: visible;
  padding: 10px 2px 68px;
}

.cat-swiper :deep(.swiper-wrapper) {
  align-items: stretch;
}

.cat-swiper-slide {
  height: auto;
}

.cat-swiper :deep(.swiper-button-prev),
.cat-swiper :deep(.swiper-button-next) {
  top: auto;
  bottom: 0;
  width: 40px;
  height: 40px;
  padding: 0;
  margin: 0;
  display: grid;
  place-items: center;
  font-size: 22px;
  font-weight: 900;
  line-height: 1;
  background: #fff;
  border: 3px solid #0f172a;
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-control);
  color: #0f172a;
  cursor: pointer;
}

.cat-swiper :deep(.swiper-button-prev::after),
.cat-swiper :deep(.swiper-button-next::after) {
  font-size: 22px;
  font-weight: 900;
}

.cat-swiper :deep(.swiper-button-prev) {
  left: auto;
  right: 54px;
}

.cat-swiper :deep(.swiper-button-next) {
  right: 2px;
}

.cat-swiper :deep(.swiper-button-disabled) {
  opacity: 0.35;
  cursor: not-allowed;
  box-shadow: none;
}

.cat-swiper :deep(.swiper-pagination) {
  bottom: 14px;
  left: 2px;
  width: auto;
  display: flex;
  gap: 10px;
  align-items: center;
}

.cat-swiper :deep(.swiper-pagination-bullet) {
  appearance: none;
  -webkit-appearance: none;
  display: block;
  width: 10px;
  height: 10px;
  padding: 0;
  margin: 0;
  border: 2px solid #0f172a;
  border-radius: 999px;
  background: #fff;
  cursor: pointer;
}

.cat-swiper :deep(.swiper-pagination-bullet-active) {
  background: #0f172a;
}

/* 拍立得卡片通用样式 */
.cat-polaroid {
  background: #fff;
  padding: 16px 16px 40px;
  width: 280px;
  transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  cursor: pointer;
  position: relative;
  margin: 0 auto; /* 轮播中居中 */
}

.desktop-only .cat-polaroid {
  transform: rotate(var(--rotate)) translateY(var(--translate-y));
}

@media (min-width: 768px) {
  .cat-polaroid:hover {
    transform: rotate(0deg) scale(1.05) translateY(-10px);
    z-index: 50 !important;
    box-shadow: 15px 15px 0 #000;
  }
}

.polaroid-img {
  position: relative;
  aspect-ratio: 1;
  overflow: hidden;
  border: 3px solid #000;
}

.polaroid-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.gender-tag {
  position: absolute;
  top: 10px;
  right: 10px;
  margin: 0;
}

.polaroid-content {
  margin-top: 16px;
}

.cat-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}

.cat-name {
  font-size: 24px;
  font-weight: 900;
  letter-spacing: -0.02em;
}

.cat-loc {
  font-size: 14px;
  color: var(--text-tertiary);
  font-weight: 700;
}

.cat-tags {
  margin-top: 8px;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.mini-tag {
  font-size: 12px;
  font-weight: 800;
  color: var(--text-secondary);
}

.cat-stats-row {
  margin-top: 16px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.stat-item {
  text-align: center;
  padding: 4px;
  border-top: 2px dashed rgba(15, 23, 42, 0.1);
}

.stat-item small {
  display: block;
  font-size: 8px;
  color: var(--text-tertiary);
  font-weight: 900;
  letter-spacing: 0.05em;
  margin-bottom: 2px;
}

.stat-item strong {
  display: block;
  font-size: 11px;
  font-weight: 800;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.cat-footer-id {
  position: absolute;
  bottom: 12px;
  right: 16px;
  font-size: 10px;
  font-family: monospace;
  font-weight: 900;
  opacity: 0.3;
}

.gallery-divider {
  margin: 40px 0 24px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.gallery-divider-title { font-weight: 900; font-size: 14px; letter-spacing: 0.1em; }
.gallery-divider-line { flex: 1; height: 2px; background: #000; }
.gallery-divider-meta { font-size: 10px; font-weight: 700; color: var(--text-tertiary); }

@media (max-width: 767px) {
  .cat-swiper {
    width: calc(100% - 28px);
  }

  .cat-polaroid {
    width: 100%;
  }
}
</style>
