import { h, resolveComponent } from 'vue'
import { createRouter, createWebHistory } from 'vue-router'
import HomeView from '@/views/index.vue'
import ProjectsView from '@/views/ProjectsView.vue'
import CatsView from '@/views/CatsView.vue'
import CocktailsView from '@/views/CocktailsView.vue'
import MotorcyclesView from '@/views/MotorcyclesView.vue'
import ContactView from '@/views/ContactView.vue'
import ProjectDetailView from '@/views/ProjectDetailView.vue'
import { applyRouteSeo } from '@/utils/seo'

const ProjectsRouteView = {
  name: 'ProjectsRouteView',
  render() {
    return h(resolveComponent('router-view'))
  }
}

const routes = [
  {
    path: '/',
    name: 'home',
    component: HomeView,
    meta: {
      title: 'Terence | 个人网站',
      description: 'Terence 的个人网站，展示开发过的项目，并记录猫咪、鸡尾酒、摩托车等兴趣爱好内容。',
      schemaType: 'WebSite'
    }
  },
  {
    path: '/projects',
    component: ProjectsRouteView,
    children: [
      {
        path: '',
        name: 'projects',
        component: ProjectsView,
        meta: {
          title: '项目案例 | Terence',
          description: '浏览 Terence 开发和参与过的项目案例，涵盖 Web 应用、产品实现与不同类型的实践记录。',
          schemaType: 'CollectionPage'
        }
      },
      {
        path: ':slug',
        name: 'project-detail',
        component: ProjectDetailView,
        meta: {
          image: '/favicon.ico',
          ogType: 'article',
          schemaType: 'CreativeWork'
        }
      }
    ]
  },
  {
    path: '/cats',
    alias: '/cat',
    name: 'cats',
    component: CatsView,
    meta: {
      title: '猫咪相册 | Terence',
      description: 'Terence 的猫咪相册页面，记录日常猫咪照片与生活片段。',
      schemaType: 'CollectionPage'
    }
  },
  {
    path: '/cocktails',
    alias: '/cocktail',
    name: 'cocktails',
    component: CocktailsView,
    meta: {
      title: '鸡尾酒记录 | Terence',
      description: 'Terence 的鸡尾酒记录页面，整理不同酒款、配方、地点与时间信息。',
      schemaType: 'CollectionPage'
    }
  },
  {
    path: '/motorcycles',
    alias: '/motorcycle',
    name: 'motorcycles',
    component: MotorcyclesView,
    meta: {
      title: '摩托车记录 | Terence',
      description: 'Terence 的摩托车页面，包含车辆信息、日常照片与骑行相关记录。',
      schemaType: 'CollectionPage'
    }
  },
  {
    path: '/contact',
    name: 'contact',
    component: ContactView,
    meta: {
      title: '联系我 | Terence',
      description: '联系 Terence，讨论设计、开发合作、新项目机会或其他创意交流。',
      schemaType: 'ContactPage'
    }
  }
]

const router = createRouter({
  history: createWebHistory(process.env.BASE_URL),
  routes,
  scrollBehavior(to, from, savedPosition) {
    if (savedPosition) {
      return savedPosition
    }

    return { top: 0, left: 0 }
  }
})

router.afterEach((to) => {
  applyRouteSeo(to)
})

export default router
